import { AppError } from "../errors/app-error.js";
export class ConfigValidationError extends AppError {
    issues;
    constructor(issues) {
        super("CONFIG_INVALID", `Invalid configuration:\n${issues.map((issue) => `- ${issue.path}: ${issue.message}`).join("\n")}`);
        this.issues = issues;
        this.name = "ConfigValidationError";
    }
}
