import { AppError } from "../errors/app-error.js";
export class ThemeValidationError extends AppError {
    issues;
    constructor(issues) {
        super("THEME_INVALID", `Invalid theme:\n${issues.map((issue) => `- ${issue.path}: ${issue.message}`).join("\n")}`);
        this.issues = issues;
        this.name = "ThemeValidationError";
    }
}
